#include "mods/mod_actor_budget.h"
#include <cassert>
int main(){using namespace mod_actor::budget;Usage usage;std::string why;std::vector<Record> records={{"one","shared",11,364752,13808,10960,1620,true,true},{"one","shared",11,364752,13808,10960,1620,true,true}};assert(check(records,11,usage,why));assert(usage.room==364752+13808+2*(10960+1620));assert(usage.mods.at("one")==usage.room);records[0].active=false;assert(check(records,11,usage,why)&&usage.room==364752+13808+10960+1620);records[1].active=false;assert(check(records,11,usage,why)&&usage.room==364752+13808);records[0].loaded=records[1].loaded=false;assert(check(records,11,usage,why)&&usage.room==0);records[0].loaded=true;records[0].backing=uint32_t(ModelLimit);records[0].resource=1;assert(!check(records,11,usage,why));records.clear();for(int i=0;i<5;++i)records.push_back({"one",std::to_string(i),0,uint32_t(ModelLimit),0,0,0,true,false});assert(!check(records,0,usage,why)&&why.find(mib(ModLimit))!=std::string::npos);records.clear();for(int i=0;i<=int(RoomLimit/ModelLimit);++i)records.push_back({std::to_string(i),std::to_string(i),0,uint32_t(ModelLimit),0,0,0,true,false});assert(!check(records,0,usage,why)&&why.find("exceed "+mib(RoomLimit))!=std::string::npos);records={{"one","model",1,1,1,1024,1620,true,true}};assert(check(records,2,usage,why)&&usage.room==2&&usage.mods.at("one")==2646);return 0;}
